'use strict';
document.querySelector('.studio-toolbar').insertAdjacentHTML('afterbegin','<button id="openStoryboard">Storyboard</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="storyboardDialog"><div class="tool-heading"><div><div class="eyebrow">YOUR STORY AT A GLANCE</div><h2>Storyboard & script</h2></div><button id="closeStoryboard">Close</button></div><p class="note">Drag a scene handle or use the arrow buttons to rearrange. Scene-local sound follows its scene; tracks spanning scenes stay at project time.</p><div class="tool-row"><button id="storyAddScene">＋ Blank scene</button><button id="downloadScript">Download script notes</button><span id="storyDuration"></span></div><div id="storyboardCards" class="storyboard-grid"></div></dialog>`);
function sceneOffsets(){let at=0;return new Map(project.scenes.map(s=>{const value=at;at+=s.duration;return[s.id,value]}))}
function sceneAudioAnchors(){const offsets=sceneOffsets(),anchors=[];for(const c of tracks()){if(c.videoId)continue;const owner=project.scenes.find(s=>c.start>=offsets.get(s.id)-.001&&audioEnd(c)<=offsets.get(s.id)+s.duration+.001);if(owner)anchors.push({clip:c,sceneId:owner.id,local:c.start-offsets.get(owner.id)})}return anchors}
function placeSceneAudio(anchors){const offsets=sceneOffsets();for(const a of anchors)if(offsets.has(a.sceneId))a.clip.start=offsets.get(a.sceneId)+a.local}
function reorderScene(from,to){if(from===to||from<0||to<0||from>=project.scenes.length||to>=project.scenes.length)return;stop();if(pathEditor)finishPathEditing();const currentId=current().id,anchors=sceneAudioAnchors(),[item]=project.scenes.splice(from,1);project.scenes.splice(to,0,item);placeSceneAudio(anchors);sceneIndex=project.scenes.findIndex(s=>s.id===currentId);save();render();if($('storyboardDialog').open)renderStoryboard()}
function changeSceneDuration(s,value){const duration=clamp(Number(value)||6,1,60),index=project.scenes.indexOf(s),offset=project.scenes.slice(0,index).reduce((n,s)=>n+s.duration,0);if(s.objects.some(o=>o.keys.some(k=>k.t>duration)||(o.out??0)>duration||(o.fadeIn??0)>duration||(o.fadeOut??0)>duration||(o.expressionKeys||[]).some(k=>k.t>duration)||(o.actionBlocks||[]).some(b=>b.start+b.duration>duration+.001)||Object.values(o.bodyAnimation||{}).some(track=>track.keys.some(k=>k.t>duration+.001))||(o.footPins||[]).some(p=>p.end>duration+.001))||(s.captions||[]).some(c=>c.end>duration)||(s.cameraPath?.end??0)>duration||(s.dialogueArranged&&(s.dialogue||[]).some(l=>l.start+l.duration>duration+.001))||(s.storyCues||[]).some(c=>c.at+c.duration>duration+.001)||(s.storyShots||[]).some(c=>c.at>=duration)||tracks().some(c=>c.start>=offset&&audioEnd(c)<=offset+s.duration+.001&&audioEnd(c)>offset+duration+.001)){toast('Trim later clips, actions, fades, captions, paths or audio before shortening this scene.');return false}const anchors=sceneAudioAnchors();s.duration=duration;placeSceneAudio(anchors);time=Math.min(time,current().duration);save();render();return true}
function storyboardOpenScene(s){stop();sceneIndex=project.scenes.indexOf(s);time=0;selectLayers([]);canvasMode='select';$('storyboardDialog').close();render()}
function wireStoryboardDrag(handle,scene){handle.draggable=false;handle.style.touchAction='none';handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();handle.setPointerCapture(e.pointerId);let target=null;handle.classList.add('dragging');handle.onpointermove=event=>{document.querySelectorAll('.storyboard-card.drop-target').forEach(card=>card.classList.remove('drop-target'));const card=document.elementFromPoint(event.clientX,event.clientY)?.closest('.storyboard-card');target=card?.dataset.sceneId||null;if(target&&target!==scene.id)card.classList.add('drop-target')};const end=()=>{handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;handle.classList.remove('dragging');document.querySelectorAll('.storyboard-card.drop-target').forEach(card=>card.classList.remove('drop-target'));if(target&&target!==scene.id)reorderScene(project.scenes.findIndex(s=>s.id===scene.id),project.scenes.findIndex(s=>s.id===target))};handle.onpointerup=end;handle.onpointercancel=()=>{target=null;end()}}}
async function renderStoryThumbnail(canvas,s){try{const images=s.objects.filter(o=>o.type==='image').map(o=>o.src);if(s.backgroundImage)images.push(s.backgroundImage);await Promise.all(images.map(src=>imageReady(src).catch(()=>{})));for(const o of s.objects.filter(o=>o.type==='video'&&visibleAt(o,0,s))){const video=videoFor(o);await mediaReady(video);await seekVideo(video,o.sourceOffset)}if(!canvas.isConnected)return;renderSceneFrame(canvas.getContext('2d'),s,0)}catch{const c=canvas.getContext('2d');c.fillStyle=s.bg;c.fillRect(0,0,canvas.width,canvas.height)}}
function renderStoryboard(){$('storyDuration').textContent=project.scenes.length+' scenes · '+totalDuration().toFixed(1)+' seconds';const grid=$('storyboardCards');grid.replaceChildren();project.scenes.forEach((s,i)=>{const card=document.createElement('article');card.className='storyboard-card'+(i===sceneIndex?' current':'');card.dataset.sceneId=s.id;const top=document.createElement('div');top.className='storyboard-card-top';const handle=document.createElement('button');handle.className='story-drag-handle';handle.textContent='⠿  SCENE '+String(i+1).padStart(2,'0');handle.draggable=true;handle.title='Drag to rearrange this scene';handle.ondragstart=e=>{e.dataTransfer.setData('text/plain',s.id);e.dataTransfer.effectAllowed='move'};const open=document.createElement('button');open.textContent='Open';open.onclick=()=>storyboardOpenScene(s);wireStoryboardDrag(handle,s);top.append(handle,open);const canvas=document.createElement('canvas');canvas.width=384;canvas.height=216;canvas.className='story-thumbnail';canvas.setAttribute('aria-label',s.name+' opening frame');canvas.onclick=()=>storyboardOpenScene(s);const title=document.createElement('input');title.value=s.name;title.maxLength=120;title.setAttribute('aria-label','Scene '+(i+1)+' name');title.onchange=()=>{s.name=title.value.trim()||'Untitled scene';save();render()};const meta=document.createElement('div');meta.className='story-card-meta';const label=document.createElement('label');label.textContent='Length ';const duration=document.createElement('input');duration.type='number';duration.min=1;duration.max=60;duration.step=.5;duration.value=s.duration;duration.setAttribute('aria-label',s.name+' duration');duration.onchange=()=>{changeSceneDuration(s,duration.value);duration.value=s.duration;renderStoryboard()};label.append(duration);const previous=document.createElement('button');previous.textContent='←';previous.title='Move scene earlier';previous.disabled=i===0;previous.onclick=()=>reorderScene(i,i-1);const next=document.createElement('button');next.textContent='→';next.title='Move scene later';next.disabled=i===project.scenes.length-1;next.onclick=()=>reorderScene(i,i+1);const transition=document.createElement('span');transition.textContent=s.transition==='cut'?'Cut':s.transition;meta.append(label,transition,previous,next);const notes=document.createElement('textarea');notes.value=s.notes||'';notes.rows=4;notes.maxLength=8000;notes.placeholder='Script / narration / production notes…';notes.setAttribute('aria-label',s.name+' script notes');notes.oninput=()=>{s.notes=notes.value;save()};card.append(top,canvas,title,meta,notes);card.ondragover=e=>{e.preventDefault();card.classList.add('drop-target')};card.ondragleave=()=>card.classList.remove('drop-target');card.ondrop=e=>{e.preventDefault();card.classList.remove('drop-target');const id=e.dataTransfer.getData('text/plain'),from=project.scenes.findIndex(s=>s.id===id),to=project.scenes.indexOf(s);reorderScene(from,to)};grid.append(card);renderStoryThumbnail(canvas,s)})}
$('openStoryboard').onclick=()=>{stop();if(pathEditor)finishPathEditing();renderStoryboard();$('storyboardDialog').showModal()};$('closeStoryboard').onclick=()=>$('storyboardDialog').close();$('storyAddScene').onclick=()=>{if(project.scenes.length>=99)return toast('Keep fewer than 100 scenes per project.');project.scenes.push(scene('Scene '+(project.scenes.length+1)));save();render();renderStoryboard()};$('downloadScript').onclick=()=>{const text=project.title+'\n\n'+project.scenes.map((s,i)=>'SCENE '+(i+1)+' · '+s.name+' · '+s.duration+'s\n'+(s.notes||'(No notes)')).join('\n\n');download(new Blob([text],{type:'text/plain'}),'elleson-storyboard-notes.txt')};
$('sceneLeft').onclick=()=>reorderScene(sceneIndex,sceneIndex-1);$('sceneRight').onclick=()=>reorderScene(sceneIndex,sceneIndex+1);$('duration').onchange=e=>{changeSceneDuration(current(),e.target.value);e.target.value=current().duration};
const storyboardValidator=valid;valid=function(p){try{return storyboardValidator(p)&&p.scenes.every(s=>(s.notes===undefined||typeof s.notes==='string'&&s.notes.length<=8000)&&['cut','fade','black','white','wipe','crossfade','slide-left','slide-right','zoom','match'].includes(s.transition))}catch{return false}};
render();
